public static Character toCharacterObject(final char ch) {
    // ASCII 7 bit characters range from 0 to 127
    if (ch >= 0 && ch <= 127) {
        // Use a cache for ASCII 7 bit characters
        Character[] asciiCache = new Character[128];
        if (asciiCache[ch] == null) {
            asciiCache[ch] = Character.valueOf(ch);
        }
        return asciiCache[ch];
    } else {
        // For characters outside the ASCII 7 bit range, use Character.valueOf
        return Character.valueOf(ch);
    }
}

