        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Check if the descriptor is a type descriptor
    if (descriptor.length() == 1) {
        switch (descriptor.charAt(0)) {
            case 'B':
            case 'C':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
            case 'J':
            case 'D':
                // Pop the appropriate number of slots
                // long and double take two slots, others take one
                if (descriptor.charAt(0) == 'J' || descriptor.charAt(0) == 'D') {
                    // Pop 2 slots
                    outputFrameStack.pop();
                    outputFrameStack.pop();
                } else {
                    // Pop 1 slot
                    outputFrameStack.pop();
                }
                return;
            case 'L':
            case '[':
                // Pop 1 object reference
                outputFrameStack.pop();
                return;
            default:
                throw new IllegalArgumentException("Invalid type descriptor: " + descriptor);
        }
    }

    // Check if the descriptor is a method descriptor
    if (descriptor.startsWith("(")) {
        int index = descriptor.indexOf(')');
        if (index == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }

        // Extract the argument descriptors
        String argumentDescriptors = descriptor.substring(1, index);

        // Initialize a pointer to traverse the argument descriptors
        int pointer = 0;

        while (pointer < argumentDescriptors.length()) {
            char c = argumentDescriptors.charAt(pointer);
            switch (c) {
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                case 'L':
                    // Pop 1 slot
                    outputFrameStack.pop();
                    pointer++;
                    break;
                case '[':
                    // Pop 1 object reference
                    outputFrameStack.pop();
                    pointer++;
                    while (pointer < argumentDescriptors.length() && argumentDescriptors.charAt(pointer) == '[') {
                        pointer++;
                    }
                    if (pointer < argumentDescriptors.length() && (argumentDescriptors.charAt(pointer) == 'L')) {
                        while (pointer < argumentDescriptors.length() && argumentDescriptors.charAt(pointer) != ';') {
                            pointer++;
                        }
                        if (pointer >= argumentDescriptors.length() || argumentDescriptors.charAt(pointer) != ';') {
                            throw new IllegalArgumentException("Invalid array type descriptor: " + descriptor);
                        }
                    }
                    pointer++;
                    break;
                case 'D':
                case 'J':
                    // Pop 2 slots
                    outputFrameStack.pop();
                    outputFrameStack.pop();
                    pointer++;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type descriptor in method descriptor: " + descriptor);
            }
        }

        return;
    }

    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
}

