                char c = argumentDescriptors.charAt(i);
                switch (c) {
                    case 'B':
                    case 'C':
                    case 'F':
                    case 'I':
                    case 'S':
                    case 'Z':
                        // Single-slot types
                        i += 1;
                        break;
                    case 'D':
                    case 'J':
