                        int endOfObject = argumentDescriptors.indexOf(';', i);
                        if (endOfObject == -1) {
                            throw new IllegalArgumentException("Invalid object type descriptor, missing ';'");
                        }
                        i = endOfObject + 1;
                        break;
                    case '[':
                        // Array type, skip through the array dimensions
                        while (i < argumentDescriptors.length() && argumentDescriptors.charAt(i) == '[') {
                            i += 1;
                        }
                        // Determine the type of the array element
                        if (i < argumentDescriptors.length()) {
                            char elementType = argumentDescriptors.charAt(i);
                            if (elementType == 'L') {
                                // Object type within array, skip to the next ';'
                                int endOfArrayObject = argumentDescriptors.indexOf(';', i);
                                if (endOfArrayObject == -1) {
                                    throw new IllegalArgumentException("Invalid object type descriptor within array, missing ';'");
                                }
                                i = endOfArrayObject + 1;
                            } else {
                                i += 1;
                            }
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid descriptor character: " + c);
                }
            }
        } else {
            // Field descriptor, pop based on the descriptor type
            switch (descriptorType) {
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                    // Single-slot types
                    break;
                case 'D':
                case 'J':
                    // Double-slot types
                    break;
                case 'L':
                    // Object type, skip to the next ';'
                    if (descriptor.indexOf(';') == -1) {
                        throw new IllegalArgumentException("Invalid object type descriptor, missing ';'");
                    }
                    break;
                case '[':
                    // Array type, skip through the array dimensions
                    int i = 0;
                    while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                        i += 1;
                    }
                    // Determine the type of the array element
                    if (i < descriptor.length()) {
                        char elementType = descriptor.charAt(i);
                        if (elementType == 'L') {
                            // Object type within array, skip to the next ';'
                            if (descriptor.indexOf(';', i) == -1) {
                                throw new IllegalArgumentException("Invalid object type descriptor within array, missing ';'");
                            }
                        }
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor character: " + descriptorType);
            }
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Malformed descriptor: " + descriptor, e);
    }
